# The JusPrin v2 model gateway's alias config (shape documented in tsd-enterprise
# web_ent/jusprin/v2/aliases.py). Read by both tsdweb-prod (GET /ent/jusprin/v2/models)
# and tsdws-prod (the /messages and /responses streams), so it lives here once.
# Pods read it at start: after changing it, restart both deployments.
# Upstream models: Standard is DeepSeek V4 Flash through OpenRouter, which sees no pictures;
# Expert is Claude Sonnet 5.5, with GPT-6.1 Sol, the mid-tier GPT-6 model, as its counterpart.
apiVersion: v1
kind: ConfigMap
metadata:
  name: jusprin-v2-gateway-prod
  namespace: default
data:
  JUSPRIN_MODEL_ALIASES: |
    {"aliases": [{
      "id": "slicer-basic", "label": "Standard", "tier": "basic", "credits": 1,
      "efforts": [], "default_effort": null,
      "backends": {
        "responses": {
          "base_url": "https://openrouter.ai/api/v1", "model": "deepseek/deepseek-v4-flash",
          "effort_map": {},
          "images": false
        }
      },
      "groups": [{"name": "responses-main", "format": "responses", "percent": 100}]
    }, {
      "id": "slicer-1", "label": "Expert", "tier": "expert", "credits": 5,
      "efforts": ["fast", "thorough"], "default_effort": "thorough",
      "backends": {
        "anthropic": {
          "base_url": "https://api.anthropic.com/v1", "model": "claude-sonnet-5-5",
          "effort_map": {"fast": "low", "thorough": "high"},
          "headers": {"anthropic-version": "2023-06-01"}
        },
        "responses": {
          "base_url": "https://api.openai.com/v1", "model": "gpt-6.1-sol",
          "effort_map": {"fast": "low", "thorough": "high"}
        }
      },
      "groups": [{"name": "anthropic-main", "format": "anthropic", "percent": 100}]
    }]}

