104	{
105	    if (!value.is_object())
106	        return false;
107	    for (const auto& item : value.items()) {
108	        if (std::none_of(allowed.begin(), allowed.end(), [&](std::string_view key) { return item.key() == key; }))
109	            return false;
110	    }
111	    return true;
