114	bool is_unsigned_string(const json& value)
115	{
116	    if (!value.is_string())
117	        return false;
118	    const std::string& text = value.get_ref<const std::string&>();
119	    if (text.empty())
120	        return false;
121	    std::uint64_t parsed = 0;
122	    const auto result = std::from_chars(text.data(), text.data() + text.size(), parsed);
123	    return result.ec == std::errc() && result.ptr == text.data() + text.size() && parsed != 0;
124	}
