// The connection types printer_host_connect takes, as OrcaSlicer's settings
// file stores them (PrintConfig.cpp, host_type): every type except the
// online services the person signs in to (obico, simplyprint, 3dprinteros),
// which take that sign-in, not an address. A type OrcaSlicer adds later is
// refused until it is listed here.
const std::vector<std::string>& host_types()
{
    static const std::vector<std::string> types{"moonraker", "octoprint", "prusalink", "prusaconnect", "duet",
                                                "ultimaker", "flashair",  "astrobox",  "repetier",     "mks",
                                                "esp3d",     "crealityprint", "flashforge", "elegoolink"};
    return types;
}

// The boxes printer_host_connect's form can ask for. PrinterConversation
// knows which printer setting each fills; the page knows its label and
// whether what is typed in it is hidden.
const std::vector<std::string>& connect_form_fields()
{
    static const std::vector<std::string> fields{"apiKey", "accessCode", "serialNumber", "userName", "password", "printerOnServer"};
    return fields;
}

bool has_only(const json& value, std::initializer_list<std::string_view> allowed)
{
    if (!value.is_object())
        return false;
    for (const auto& item : value.items()) {
        if (std::none_of(allowed.begin(), allowed.end(), [&](std::string_view key) { return item.key() == key; }))
            return false;
    }
    return true;
}

bool is_unsigned_string(const json& value)
{
    if (!value.is_string())
        return false;
    const std::string& text = value.get_ref<const std::string&>();
    if (text.empty())
        return false;
    std::uint64_t parsed = 0;
    const auto result = std::from_chars(text.data(), text.data() + text.size(), parsed);
    return result.ec == std::errc() && result.ptr == text.data() + text.size() && parsed != 0;
}

bool optional_string(const json& arguments, const char* key)
{
    return !arguments.contains(key) || arguments[key].is_string();
}

bool optional_number(const json& arguments, const char* key)
{
    return !arguments.contains(key) || arguments[key].is_number();
}

// Prose the agent writes: present or absent, a string either way, and bounded
// so one answer cannot fill a context window.
bool optional_text(const json& arguments, const char* key)
{
    return !arguments.contains(key) ||
           (arguments[key].is_string() && arguments[key].get_ref<const std::string&>().size() <= kToolTextLimit);
}

